  import java.io.BufferedReader;
  import java.io.File;
  import java.io.FileReader;
  import java.util.ArrayList;
  import java.util.HashMap;
  import java.util.List;
  import sailpoint.api.SailPointContext;
  import sailpoint.object.Attributes;
  import sailpoint.tools.Util;
  import sailpoint.object.ObjectConfig;
  import sailpoint.task.AbstractTaskExecutor;
  import sailpoint.tools.GeneralException;
  import sailpoint.tools.RFC4180LineParser;
  import sailpoint.api.Describer;
  import java.util.Iterator;
  import java.time.format.DateTimeFormatter;
  import java.io.FileWriter;
  import java.util.Date;
  import java.util.ArrayList;
  import sailpoint.api.SailPointContext;
  import sailpoint.object.Schema;
  import java.util.*;
  import sailpoint.object.QueryOptions;
  import sailpoint.object.Filter;
  import sailpoint.object.ManagedAttribute;
  import sailpoint.object.Application;
  import sailpoint.object.Identity;


  public void managedAttributeCreate() throws GeneralException 
  {
    try 
    {

      String dlm = ",";

      String csvFileName = "E:/skyview/managedAttributeCreate.csv"; 

      File testFile = new File(csvFileName);

      if ((!testFile.exists()) || (testFile.isDirectory())) 
      {
        System.out.println("Unable to find file: "+csvFileName);
        return;    
      }

      System.out.println("Importing data from: '" + csvFileName + "' ...");

      BufferedReader fileIn = new BufferedReader(new FileReader(csvFileName));

      RFC4180LineParser parser = new RFC4180LineParser(dlm);


      int lineCounter = 0;
      ArrayList<String> headerStrings = new ArrayList<String>();
      String thisLine = null;

      while (null != (thisLine = fileIn.readLine())) 
      {

        List < String> tokens = parser.parseLine(thisLine);
        if (lineCounter == 0) 
        {
          for (int i=0; i < tokens.size(); i++) 
          {
            headerStrings.add(tokens.get(i).trim());
          }	  
        } 
        else 
        {
          HashMap lineHash = new HashMap();
          for (int i=0; i < tokens.size(); i++) 
          {
            String headerString = headerStrings.get(i);
            String valueString = tokens.get(i);
            if (null != valueString) 
            {
              valueString = valueString.trim(); 
            }
            lineHash.put(headerString, valueString);
          }

          String roleName = lineHash.get("RoleName");



		  String value="cn=test2,ou=EmployeeCenteGroup,dc=skyview,dc=com"; // lineHash.get("value");
		  String application=lineHash.get("application");
		  String type=lineHash.get("type");
		  String attribute=lineHash.get("attribute");
		  String displayName=lineHash.get("displayName");
		  String requestable=lineHash.get("requestable");
		  String description=lineHash.get("description");
		  String owner=lineHash.get("owner");

		  QueryOptions qo = new QueryOptions();

		   Filter entFilter = Filter.and(Filter.eq("value",value), Filter.eq("displayName",displayName),Filter.eq("application.name",application));
		 // Filter entFilter = Filter.eq("application.name","Sky - LDAP");
		  qo.add(entFilter);

		  List entList=context.getObjects(ManagedAttribute.class,qo);
		  System.out.println("############################################## List of ents: ################# "+ entList+ "  "+ entList.isEmpty());
			if(entList.isEmpty() || entList==null)  
		  {
			// Create ManageAttribute
			System.out.println("No such ManagedAttribute exist, Creating new one:");
			ManagedAttribute newEnt =new ManagedAttribute();

			newEnt.setValue(value);
			newEnt.setApplication(context.getObjectByName(Application.class,application));
			newEnt.setType(type);
			newEnt.setAttribute(attribute);
			newEnt.setDisplayName(displayName);
			if(requestable.equalsIgnoreCase("true"))
				newEnt.setRequestable(true);
			else
			  newEnt.setRequestable(false);
			if(description!=null)
			newEnt.addDescription("en_US", description);
			newEnt.setOwner(context.getObjectByName(Identity.class,owner));

			System.out.println("New entitlement created :  " + value);
			context.saveObject(newEnt);
			context.commitTransaction();
			 System.out.println("New entitlement created :  " + value);

		  }
		  else
		  {
			  System.out.println("ManagedAttribute exist,Skipping creation: "+ value);
		  }







        }

        lineCounter++;
      }

      fileIn.close();

    }
    catch(Exception e)
    {
      e.printStackTrace();
    }


  }

  managedAttributeCreate();
